<?php
// Render the real report view without connecting to or changing business records.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
date_default_timezone_set('Asia/Singapore');
$source = str_replace("\r\n", "\n", file_get_contents(dirname(__DIR__) . '/public/reports_module/reports.php'));
$helpersStart = strpos($source, 'function reports_money(');
$helpersEnd = strpos($source, '$stmt =', $helpersStart);
eval(substr($source, $helpersStart, $helpersEnd - $helpersStart));
function is_admin() { return $GLOBALS['testRole'] === 'admin'; }
function is_manager() { return $GLOBALS['testRole'] === 'manager'; }
function current_user_role() { return $GLOBALS['testRole']; }
function role_display_name($role) { return ucfirst($role); }
function can($capability) { return $GLOBALS['testExport']; }
$checks = 0;
function check($value, $label) { global $checks; if (!$value) throw new RuntimeException('FAIL: ' . $label); $checks++; echo 'PASS: ', $label, PHP_EOL; }
function render_reports(array $variables): DOMXPath {
    global $source;
    $start = strpos($source, '<main '); $end = strpos($source, '</main>', $start) + strlen('</main>');
    extract($variables); ob_start(); eval('?>' . substr($source, $start, $end - $start)); $html = ob_get_clean();
    $document = new DOMDocument(); @$document->loadHTML('<!doctype html><meta charset="utf-8">' . $html);
    return new DOMXPath($document);
}
$reports = [];
for ($i = 1; $i <= 4; $i++) $reports[] = ['report_date' => '2026-10-0' . $i, 'total_orders' => 13, 'total_sales' => 2903.75, 'generated_by_display' => $i === 4 ? '<script>Unsafe</script>' : 'Manager', 'generated_at' => '2026-10-0' . $i . ' 18:30:00'];
$variables = ['filterDate' => '2026-10-09', 'selectedReport' => false, 'ordersExist' => true, 'inventoryExist' => true, 'reportsExist' => true, 'reportCount' => 4, 'totalOrders' => 52, 'totalSales' => 11615.00, 'latestReport' => $reports[3], 'dailyReports' => $reports, 'voidedOrders' => ['2026-10-01' => 2], 'selectedVoids' => 2, 'selectedSales' => 820.00, 'selectedOrders' => 2, 'selectedGeneratedBy' => 'Manager', 'selectedPayments' => ['collected' => 820, 'successful_count' => 2, 'pending_count' => 0, 'failed_count' => 0]];
$GLOBALS['testRole'] = 'manager'; $GLOBALS['testExport'] = true;
$x = render_reports($variables);
check($x->query('//main[contains(@class,"sales-reports-workspace")]')->length === 1 && $x->query('//h1[@id="reports-title"]')->item(0)->textContent === 'Daily Reports', 'The real reports template exposes its heading and dedicated workspace');
check($x->query('//*[@data-sales-report-history and @tabindex="0" and @role="region" and @aria-labelledby="reports-history-title"]')->length === 1, 'Generated history has one keyboard-accessible scrolling region');
check($x->query('//table/thead/tr/th')->length === 7 && $x->query('//table/tbody/tr')->length === 4, 'All seven history fields and four saved reports remain available');
check($x->query('//table/tbody/tr/td[@data-label]')->length === 28, 'Every report field has a visible label when displayed as a mobile card');
check($x->query('//*[contains(@class,"reports-selected-panel")]//*[contains(@class,"reports-empty-state")]')->length === 1 && $x->query('//*[contains(@class,"reports-selected-grid")]')->length === 0, 'A date without a generated report retains its honest empty state');
check($x->query('//a[contains(@href,"generate_daily_report.php?date=2026-10-09")]')->length === 2, 'Both existing single-date generation links retain the selected date');
check($x->query('//a[@href="manager_settings.php"]')->length === 1 && $x->query('//a[@href="backup_restore.php"]')->length === 0, 'Managers keep Forecast Settings without administrator backup access');
check($x->query('//a[contains(@href,"export_daily_report_excel.php")]')->length === 4 && $x->query('//a[contains(@href,"view_daily_report.php")]')->length === 4, 'Existing report view and permitted Excel actions are retained for every row');
check($x->query('//form[@id="rangeToolsForm" and @hidden]//input[@name="from" and @required]')->length === 1 && $x->query('//button[@id="btnExportRange"]')->length === 1, 'Range tools retain their form, validation inputs and export control');
check($x->query('//script')->length === 0 && str_contains($x->query('//table/tbody/tr[4]/td[@data-label="Generated By"]')->item(0)->textContent, '<script>Unsafe</script>'), 'Generated-by text remains escaped safely');
$variables['selectedReport'] = ['report_date' => '2026-10-09'];
$x = render_reports($variables);
check($x->query('//*[contains(@class,"reports-selected-grid")]/div')->length === 7 && $x->query('//*[contains(@class,"reports-selected-panel")]//*[contains(@class,"reports-empty-state")]')->length === 0, 'An existing report displays all sales, order, void and payment summary fields');
check($x->query('//*[contains(@class,"reports-selected-grid")]/div[1]/strong')->item(0)->textContent === 'PHP 820.00' && $x->query('//*[contains(@class,"reports-selected-grid")]/div[5]/strong')->item(0)->textContent === 'PHP 820.00', 'Sales and payment values are displayed without changing their amounts');
check($x->query('//*[contains(@class,"reports-selected-panel")]//a[@href="view_daily_report.php?date=2026-10-09"]')->length === 1, 'Generated dates retain their detailed report action');
$GLOBALS['testRole'] = 'admin'; $x = render_reports($variables);
check($x->query('//a[@href="backup_restore.php"]')->length === 1 && $x->query('//a[@href="inventory.php"]')->length === 1, 'Administrators retain Backup and Inventory navigation');
$GLOBALS['testExport'] = false; $x = render_reports($variables);
check($x->query('//a[contains(@href,"export_daily_report_excel.php")]')->length === 0 && $x->query('//table/tbody/tr')->length === 4, 'The existing export capability still controls row export actions');
$variables['selectedReport'] = false; $variables['dailyReports'] = []; $variables['reportsExist'] = false; $variables['reportCount'] = 0; $variables['latestReport'] = null;
$x = render_reports($variables);
check($x->query('//*[@data-sales-report-history]//*[contains(@class,"reports-empty-state")]')->length === 1, 'Empty history uses the same accessible frame as populated history');
check($x->query('//*[contains(@class,"reports-notice") and @role="status"]')->length === 1, 'A first-time report page retains its generation notice');
check($x->query('//form[@id="dateFilterForm"]//input[@name="report_date"]')->item(0)->getAttribute('value') === '2026-10-09', 'The date filter retains the chosen date in all report states');
echo 'All ', $checks, ' report rendering checks passed.', PHP_EOL;
